    'OpenHumanの1時間あたりのアクション上限に達しました。これはローカルの安全制限であり、AIプロバイダーの制限ではありません。制限は徐々に緩和されます。このスレッドでのチャットは継続できますが、ツールを多用する処理は予算が回復するまで一時停止します。',
