    'エージェントが1回のターンで実行可能なツールステップの最大数に達しましたが、処理を完了できませんでした。これは通常、ツールの実行が失敗し続けていることを意味します（多くの場合、Web取得のレート制限が原因です）。根本的な制限が解消されたら、このスレッドで同じ質問を再試行してください。',
